<?php

declare(strict_types=1);

namespace Identity\Application\Command\SecondFactor;

use Identity\Application\SecondFactor\CodeVerification;
use Shared\Application\Audit\AuditAction;
use Shared\Application\Audit\AuditContext;
use Shared\Application\Audit\SelfAuditedCommand;
use Shared\Application\Audit\Target;
use Shared\Application\Security\RevealsSecret;

/**
 * Confirms a pending TOTP enrolment with a first code. On acceptance only, TOTP is active and the backup codes (generated by the UI, shown once) are stored hashed.
 */
final readonly class ConfirmTotp implements SelfAuditedCommand, CodeVerification, RevealsSecret
{
    /**
     * @param list<string> $backupCodes
     */
    public function __construct(
        public string $userId,
        #[\SensitiveParameter] public string $code,
        public string $attemptId,
        #[\SensitiveParameter] public array $backupCodes,
    ) {
    }

    public function auditAction(): AuditAction
    {
        return AuditAction::named('identity.confirm_totp');
    }

    public function auditTarget(): Target
    {
        return Target::of('user', $this->userId);
    }

    public function auditContext(): AuditContext
    {
        return AuditContext::empty();
    }
}
